    'psrv.faq.q1': 'Faut-il absolument un rendez-vous ?',
    'psrv.faq.a1': "Oui, la prise de rendez-vous est obligatoire pour tout dépôt de dossier. Aucun dossier ne sera accepté sans rendez-vous préalable. Vous pouvez prendre rendez-vous par téléphone ou par email.",
    'psrv.faq.q2': "Combien de temps dure le traitement d'un passeport ?",
    'psrv.faq.a2': "Le délai moyen de traitement d'un passeport biométrique est de 4 à 8 semaines. Ce délai dépend des conditions de traitement à Abidjan. En cas d'urgence dûment justifiée, un passeport d'urgence peut être délivré sous 24 à 72 heures.",
    'psrv.faq.q3': 'Les frais sont-ils remboursables en cas de refus ?',
    'psrv.faq.a3': "Non, les frais consulaires sont non remboursables, y compris en cas de refus de la demande. Il est donc important de s'assurer que votre dossier est complet avant de le déposer.",
    'psrv.faq.q4': 'Puis-je envoyer mon dossier par courrier postal ?',
    'psrv.faq.a4': "Pour certaines demandes simples (légalisation de copies, certains certificats), l'envoi par courrier recommandé est possible. Pour les demandes de passeport et de CNI, la présence physique du demandeur est obligatoire pour la prise d'empreintes biométriques.",
    'psrv.faq.q5': 'Je réside en Hongrie, puis-je effectuer mes démarches à Vienne ?',
    'psrv.faq.a5': "Oui, l'Ambassade de Côte d'Ivoire à Vienne est compétente pour tous les ressortissants ivoiriens résidant en Autriche, Hongrie, Slovénie, Slovaquie, Croatie, Serbie, Roumanie et Bosnie-Herzégovine. Vous devez vous déplacer à Vienne pour effectuer vos démarches.",
