    'dl.info.text':  'Die Formulare sind vor Ihrem Termin auszudrucken, auszufüllen und zu unterschreiben. Alle Zahlungen erfolgen ausschließlich online.',
    'dl.f01.eyebrow':'Reisepass', 'dl.f01.title':'Antragsformular für den Reisepass', 'dl.f01.sub':'Gewöhnlicher / biometrischer Reisepass im Ausland', 'dl.f01.desc':'Offizielles Formular des Sicherheitsministeriums. Vor Ihrem Konsulartermin auszufüllen und zu unterschreiben. Bitte die erforderlichen Belege beifügen.', 'dl.f01.size':'PDF · 68 KB',
    'dl.f02.eyebrow':'Registrierung', 'dl.f02.title':'Konsularisches Registrierungsformular', 'dl.f02.sub':'Eintragung in das Register der Ivorer im Ausland', 'dl.f02.desc':'Verpflichtend für alle ivorischen Staatsangehörigen mit Wohnsitz in Österreich. Die Registrierung erleichtert den Zugang zu konsularischen Dienstleistungen und schützt Ihre Rechte im Ausland.', 'dl.f02.size':'PDF · 124 KB',
    'dl.f03.eyebrow':'Minderjährige', 'dl.f03.title':'Elterliche Erklärung', 'dl.f03.sub':'Genehmigung für Reisepass und/oder Geburtsurkunde eines minderjährigen Kindes', 'dl.f03.desc':'Von den Elternteilen erteilte Genehmigung zur Ausstellung eines Reisepasses oder einer Geburtsurkunde für ein minderjähriges Kind. Beglaubigte Unterschrift erforderlich.', 'dl.f03.size':'PDF · 100 KB',
    'dl.f04.eyebrow':'Visum', 'dl.f04.title':'Antragsformular für das Visum', 'dl.f04.sub':'Gewöhnliches, Höflichkeits- oder Diplomatenvisum', 'dl.f04.desc':'Formular für jeden Antrag auf ein Einreisevisum nach Côte d\'Ivoire. Alle Pflichtfelder sind vollständig auszufüllen. Ein aktuelles Passfoto ist erforderlich.', 'dl.f04.size':'PDF · 125 KB',
    'dl.f05.eyebrow':'Personenstand', 'dl.f05.title':'Umschreibung der Geburtsurkunde', 'dl.f05.sub':'Im Ausland geborene Kinder ivorischer Eltern', 'dl.f05.desc':'Formular zur Eintragung einer im Ausland ausgestellten Geburtsurkunde in die ivorischen Personenstandsregister. Verpflichtend für den Erwerb der Staatsangehörigkeit und des Reisepasses.', 'dl.f05.size':'PDF · 131 KB',
    'dl.f06.eyebrow':'Vollmacht', 'dl.f06.title':'Konsularische Vollmacht', 'dl.f06.sub':'Mandat zum Handeln im Namen eines Dritten', 'dl.f06.desc':'Ermöglicht einer bevollmächtigten Person, Verwaltungsangelegenheiten in Ihrem Namen bei der Botschaft oder auf ivorischem Staatsgebiet zu erledigen.', 'dl.f06.size':'PDF · 89 KB',
    'dl.f07.eyebrow':'Beglaubigung', 'dl.f07.title':'Antrag auf Beglaubigung', 'dl.f07.sub':'Beglaubigung von Verwaltungs- oder notariellen Dokumenten', 'dl.f07.desc':'Formular zur Beglaubigung ivorischer oder ausländischer Dokumente, die in Côte d\'Ivoire oder einem Drittland verwendet werden sollen. Gilt für notarielle, verwaltungstechnische und kommerzielle Urkunden.', 'dl.f07.size':'PDF · 121 KB',
    'dl.f08.eyebrow':'Passierschein', 'dl.f08.title':'Antrag auf einen Passierschein', 'dl.f08.sub':'Vorläufiges Reisedokument im Notfall', 'dl.f08.desc':'Vorübergehendes Reisedokument bei Verlust, Diebstahl oder Ablauf des Reisepasses. Gültig für eine einfache Reise nach Côte d\'Ivoire.', 'dl.f08.size':'PDF · 139 KB',
    'dl.f09.eyebrow':'Staatsangehörigkeit', 'dl.f09.title':'Verzicht auf die ivorische Staatsangehörigkeit', 'dl.f09.sub':'Antrag auf Bescheinigung der Verzichtsübermittlung', 'dl.f09.desc':'Formular zur Einleitung des Verfahrens zum Verzicht auf die ivorische Staatsangehörigkeit. Bei der Botschaft einzureichen, zusammen mit den erforderlichen Belegen.', 'dl.f09.size':'PDF · 89 KB',
