    'cc.docs.email.note': 'Bitte senden Sie nach dem Absenden dieses Formulars eine Kopie aller oben genannten Unterlagen per E-Mail an <strong>sceconsul.autriche@diplomatie.gouv.ci</strong> und geben Sie Ihren Namen und Vornamen als Betreff an.',
    'cc.f.submit': 'Antrag senden →',
    'cc.status.sending': 'Wird gesendet…',
    'cc.status.success': '✓ Antrag erfolgreich gesendet!',
    'cc.status.error': 'Fehler beim Senden. Bitte versuchen Sie es erneut oder kontaktieren Sie uns direkt.',
    'psrv.faq.q1': 'Ist ein Termin zwingend erforderlich?',
    'psrv.faq.a1': 'Ja, die Terminvereinbarung ist für die Einreichung von Unterlagen obligatorisch. Es werden keine Unterlagen ohne vorherigen Termin angenommen. Termine können telefonisch oder per E-Mail vereinbart werden.',
    'psrv.faq.q2': 'Wie lange dauert die Bearbeitung eines Reisepasses?',
    'psrv.faq.a2': 'Die durchschnittliche Bearbeitungszeit für einen biometrischen Reisepass beträgt 4 bis 8 Wochen. Diese Frist hängt von den Bearbeitungsbedingungen in Abidjan ab. In nachgewiesenen Notfällen kann ein Notreisepass innerhalb von 24 bis 72 Stunden ausgestellt werden.',
    'psrv.faq.q3': 'Werden Gebühren bei Ablehnung erstattet?',
    'psrv.faq.a3': 'Nein, die Konsulargebühren sind nicht erstattungsfähig, auch nicht bei Ablehnung des Antrags. Es ist daher wichtig sicherzustellen, dass Ihre Unterlagen vollständig sind, bevor Sie sie einreichen.',
    'psrv.faq.q4': 'Kann ich meine Unterlagen per Post einsenden?',
    'psrv.faq.a4': 'Für bestimmte einfache Anträge (Beglaubigung von Kopien, bestimmte Bescheinigungen) ist die Einsendung per Einschreiben möglich. Für Reisepass- und Personalausweisanträge ist die persönliche Anwesenheit des Antragstellers zur biometrischen Erfassung zwingend erforderlich.',
    'psrv.faq.q5': 'Ich wohne in Ungarn — kann ich meine Angelegenheiten in Wien erledigen?',
    'psrv.faq.a5': 'Ja, die Botschaft von Côte d\'Ivoire in Wien ist für alle ivorischen Staatsangehörigen zuständig, die in Österreich, Ungarn, Slowenien, der Slowakei, Kroatien, Serbien, Rumänien und Bosnien-Herzegowina wohnen. Sie müssen für Ihre Angelegenheiten nach Wien kommen.',
    'pcon.h1':       'Kontakt & Öffnungszeiten',
