    /* Article titles & descriptions */
    'ann.a1.title': 'Economic mission: Aka Aouélé leads a delegation of the Economic, Social, Environmental and Cultural Council (CESEC) to Austria',
    'ann.a1.desc':  "The President of the CESEC, Aka Aouélé, led an Ivorian delegation to Austria to strengthen exchanges and cooperation between Côte d'Ivoire and its European partners.",
    'ann.a2.title': "Ivorian diplomacy honoured in Vienna: Côte d'Ivoire assumes the presidency of the Comprehensive Nuclear-Test-Ban Treaty Organisation (CTBTO)",
    'ann.a2.desc':  "Côte d'Ivoire assumed the presidency of the Preparatory Commission of the Comprehensive Nuclear-Test-Ban Treaty Organisation (CTBTO), marking a major milestone for Ivorian diplomacy on the international stage in Vienna.",
    'ann.a3.title': "Civil nuclear energy: Côte d'Ivoire advocates for stronger support from the International Atomic Energy Agency (IAEA)",
    'ann.a3.desc':  "Côte d'Ivoire expressed in Vienna, during the IAEA proceedings, its desire to benefit from enhanced support for the development of its civil nuclear programme.",
    'ann.a4.title': 'Ivorian diplomacy in Austria: Ambassador Cissé Yacouba meets with the Governor of Vorarlberg',
    'ann.a4.desc':  "His Excellency Mr Cissé Yacouba, Ambassador of Côte d'Ivoire to Austria, met with the Governor of the State of Vorarlberg as part of efforts to strengthen bilateral relations between Côte d'Ivoire and Austria.",
    'ann.a5.title': 'Official communiqué — Presentation of letters of credence',
    'ann.a5.desc':  "His Excellency Mr Cissé Yacouba, Ambassador Extraordinary and Plenipotentiary of the Republic of Côte d'Ivoire, presented his letters of credence to the Federal President of the Republic of Austria at an official ceremony at the Hofburg Palace in Vienna.",
    'ann.a6.title': "Côte d'Ivoire and the CTBTO seal a nuclear security partnership in Abidjan",
    'ann.a6.desc':  "On 26 June 2026 in Abidjan, Côte d'Ivoire and the Comprehensive Nuclear-Test-Ban Treaty Organization (CTBTO) signed a partnership agreement to strengthen the International Monitoring System (IMS). Ambassador Cissé Yacouba represented the Ivorian delegation alongside Foreign Minister Nialé Kaba and Executive Secretary Robert Floyd.",
    'ann.a6.date':  "26 June 2026",

