    'ann.sub.title':'Kapja meg a közleményeket','ann.sub.desc':'Iratkozzon fel, hogy értesüljön az új közleményekről és fontos információkról.','ann.sub.btn':'Feliratkozás az értesítésekre',
    'ann.a1.title':'Gazdasági küldöttség: Aka Aouélé a Gazdasági, Szociális, Környezetvédelmi és Kulturális Tanács (CESEC) küldöttségét vezeti Ausztriába','ann.a1.desc':'A CESEC elnöke, Aka Aouélé, ivóri küldöttséget vezetett Ausztriába egy gazdasági küldetés keretében, amelynek célja az Elefántcsontpart és európai partnerei közötti kapcsolatok és együttműködés erősítése.',
    'ann.a2.title':'Az ivóri diplomácia elismerése Bécsben: Elefántcsontpart tölti be az Átfogó Atomcsend-egyezmény Szervezetének elnökségét','ann.a2.desc':'Elefántcsontpart átvette az Átfogó Atomcsend-egyezmény Szervezete (CTBTO) Előkészítő Bizottságának elnökségét, ami fontos mérföldkövet jelent az ivóri diplomácia számára a nemzetközi színtéren, Bécsben.',
    'ann.a3.title':'Polgári nukleáris energia: Elefántcsontpart a Nemzetközi Atomenergia-ügynökség fokozott támogatását kéri','ann.a3.desc':'Elefántcsontpart Bécsben, a NAÜ munkaülésein kifejezte szándékát, hogy fokozott támogatásban részesüljön polgári nukleáris programjának fejlesztése keretében.',
    'ann.a4.title':'Ivóri diplomácia Ausztriában: Cissé Yacouba nagykövet találkozik Vorarlberg tartományi kormányzójával','ann.a4.desc':'Ő Excellenciája Cissé Yacouba úr, Elefántcsontpart ausztriai nagykövete, találkozott Vorarlberg tartomány kormányzójával az Elefántcsontpart és Ausztria közötti kétoldalú kapcsolatok erősítése keretében.',
    'ann.a5.title':'Hivatalos közlemény — Megbízólevelek átadása','ann.a5.desc':'Ő Excellenciája Cissé Yacouba úr, az Elefántcsontparti Köztársaság rendkívüli és meghatalmazott nagykövete, átadta megbízólevelét az Osztrák Köztársaság szövetségi elnökének egy hivatalos ünnepségen a bécsi Hofburg-palotában.',
    'ann.a6.title':'Elefántcsontpart és a CTBTO Abidjanban partnerségi megállapodást kötött a nukleáris biztonság területén','ann.a6.desc':'2026. június 26-án, Abidjanban, Elefántcsontpart és az Átfogó Atomcsend-egyezmény Szervezete (CTBTO) partnerségi megállapodást írt alá a Nemzetközi Megfigyelő Rendszer (IMS) megerősítése céljából. Cissé Yacouba nagykövet képviselte az ivóri küldöttséget Nialé Kaba külügyminiszter és Robert Floyd ügyvezető titkár mellett.','ann.a6.date':'2026. június 26.',
