    'ann.a1.title':'Gospodarska misija: Aka Aouélé vodi delegacijo Ekonomskega, socialnega, okoljskega in kulturnega sveta (CESEC) v Avstrijo','ann.a1.desc':'Predsednik CESEC, Aka Aouélé, je vodil ivoirsko delegacijo v Avstrijo v okviru gospodarske misije za krepitev izmenjav in sodelovanja med Slonokoščeno obalo in njenimi evropskimi partnerji.',
    'ann.a2.title':'Ivoirska diplomacija v ospredju na Dunaju: Slonokoščena obala prevzema predsedovanje Organizaciji pogodbe o celoviti prepovedi jedrskih poskusov','ann.a2.desc':'Slonokoščena obala je prevzela predsedovanje Pripravljalne komisije Organizacije pogodbe o celoviti prepovedi jedrskih poskusov (CTBTO), kar je pomemben mejnik ivoirske diplomacije na mednarodnem prizorišču na Dunaju.',
    'ann.a3.title':'Civilna jedrska energija: Slonokoščena obala poziva k okrepljeni podpori Mednarodne agencije za atomsko energijo','ann.a3.desc':'Slonokoščena obala je na Dunaju, na zasedanjih IAEA, izrazila željo po okrepljeni podpori pri razvoju svojega civilnega jedrskega programa.',
    'ann.a4.title':'Ivoirska diplomacija v Avstriji: veleposlanik Cissé Yacouba se sreča z deželnim glavarjem Vorarlberga','ann.a4.desc':'Njegova ekscelenca gospod Cissé Yacouba, veleposlanik Slonokoščene obale v Avstriji, se je srečal z deželnim glavarjem dežele Vorarlberg v okviru krepitve dvostranskih odnosov med Slonokoščeno obalo in Avstrijo.',
    'ann.a5.title':'Uradno sporočilo — Predstavitev poverilnic','ann.a5.desc':'Njegova ekscelenca gospod Cissé Yacouba, izredni in pooblaščeni veleposlanik Republike Slonokoščene obale, je predal svoje poverilnice zveznemu predsedniku Republike Avstrije na uradni slovesnosti v palači Hofburg na Dunaju.',
    'ann.a6.title':'Slonokoščena obala in CTBTO sta v Abidjanu sklenila partnerstvo na področju jedrske varnosti','ann.a6.desc':'26. junija 2026 sta v Abidjanu Slonokoščena obala in Organizacija pogodbe o celoviti prepovedi jedrskih poskusov (CTBTO) podpisali partnerski sporazum za krepitev Mednarodnega nadzornega sistema (IMS). Veleposlanik Cissé Yacouba je zastopal ivoirsko delegacijo skupaj z ministrico za zunanje zadeve Nialé Kaba in izvršnim sekretarjem Robertom Floydom.','ann.a6.date':'26. junij 2026',
