    'pays.blurb.at':'Hostiteľská krajina Veľvyslanectva. Viedeň je tiež sídlom mnohých medzinárodných organizácií (UNIDO, MAAE, UNODC).','pays.blurb.hu':'Členský štát Európskej únie ležiaci v srdci strednej Európy.','pays.blurb.si':'Alpská krajina na križovatke strednej Európy, členský štát Európskej únie.','pays.blurb.sk':'Mladá stredoeurópska republika, členský štát Európskej únie a eurozóny.','pays.blurb.hr':'Krajina pri Jadranskom mori, posledná krajina, ktorá vstúpila do Európskej únie (2013).','pays.blurb.rs':'Kandidátska krajina na vstup do Európskej únie, ležiaca v srdci Balkánu.','pays.blurb.ro':'Veľká juhovýchodoeurópska krajina, členský štát Európskej únie od roku 2007.','pays.blurb.ba':'Balkánsky štát v procese európskej integrácie, na križovatke kultúr.','pays.blurb.md':'Východoeurópsky štát približujúci sa k Európskej únii.',
