    'cta.title':'Potrebujete konzulárnu pomoc?','cta.desc':'Náš tím je vám k dispozícii pri všetkých administratívnych úkonoch. Dohodnite si stretnutie online alebo nás kontaktujte priamo.','cta.btn1':'Dohodnúť stretnutie','cta.btn2':'Zobraziť služby',
    'ann.h1':'Informácie a oznámenia','ann.desc':'Nájdete tu všetky oficiálne informácie, dôležité upozornenia a oznámenia Veľvyslanectva Pobrežia Slonoviny vo Viedni.',
    'ann.pinned.label':'Pripnuté — Naliehavé','ann.pinned.title':'Mimoriadne zatvorenie — Národný sviatok Pobrežia Slonoviny','ann.pinned.desc':'Veľvyslanectvo Pobrežia Slonoviny vo Viedni bude <strong>zatvorené v piatok 7. augusta 2026</strong> pri príležitosti Národného sviatku Republiky Pobrežia Slonoviny (66. výročie nezávislosti). Služby budú bežne pokračovať v pondelok 10. augusta 2026 od 09.30.','ann.pinned.date':'Uverejnené 25. mája 2026',
    'ann.filter.all':'Všetky','ann.filter.urgent':'Naliehavé','ann.filter.admin':'Administratívne','ann.filter.event':'Podujatia','ann.filter.communique':'Oznámenia',
    'ann.cat.mission':'Hospodárska misia','ann.cat.diplo':'Diplomacia','ann.cat.actu':'Aktuality','ann.cat.communique':'Oznámenie',
    'ann.btn.read':' Čítať článok','ann.btn.readfull':' Prečítať celé oznámenie','ann.empty':'V tejto kategórii momentálne nie sú žiadne oznámenia.',
    'ann.sidebar.links':'Užitočné odkazy','ann.sidebar.passport':'Obnovenie cestovného pasu','ann.sidebar.visa':'Žiadosť o vízum','ann.sidebar.civil':'Matričné doklady','ann.sidebar.rdv':'Dohodnúť stretnutie','ann.sidebar.hours':'Úradné hodiny','ann.sidebar.contact':'Priamy kontakt',
    'ann.sub.title':'Dostávajte oznámenia','ann.sub.desc':'Zaregistrujte sa, aby ste boli informovaní o nových oznámeniach a dôležitých informáciách.','ann.sub.btn':'Prihlásiť sa na odber upozornení',
    'ann.a1.title':'Hospodárska misia: Aka Aouélé vedie delegáciu Hospodárskej, sociálnej, environmentálnej a kultúrnej rady (CESEC) do Rakúska','ann.a1.desc':'Predseda CESEC, Aka Aouélé, viedol pobrežnoslonovinskú delegáciu do Rakúska v rámci hospodárskej misie zameranej na posilnenie výmen a spolupráce medzi Pobrežím Slonoviny a jeho európskymi partnermi.',
    'ann.a2.title':'Pobrežnoslonovinská diplomacia vo Viedni: Pobrežie Slonoviny preberá predsedníctvo Organizácie Zmluvy o všeobecnom zákaze jadrových skúšok','ann.a2.desc':'Pobrežie Slonoviny prevzalo predsedníctvo Prípravnej komisie Organizácie Zmluvy o všeobecnom zákaze jadrových skúšok (CTBTO), čo predstavuje významný míľnik pobrežnoslonovinskej diplomacie na medzinárodnej scéne vo Viedni.',
    'ann.a3.title':'Civilná jadrová energia: Pobrežie Slonoviny žiada o silnejšiu podporu Medzinárodnej agentúry pre atómovú energiu','ann.a3.desc':'Pobrežie Slonoviny vo Viedni na rokovaniach MAAE vyjadrilo záujem o posilnenú podporu v rámci rozvoja svojho civilného jadrového programu.',
    'ann.a4.title':'Pobrežnoslonovinská diplomacia v Rakúsku: veľvyslanec Cissé Yacouba rokoval s guvernérom Vorarlbergu','ann.a4.desc':'Jeho Excelencia pán Cissé Yacouba, veľvyslanec Pobrežia Slonoviny v Rakúsku, sa stretol s guvernérom spolkovej krajiny Vorarlbersko v rámci posilňovania bilaterálnych vzťahov medzi Pobrežím Slonoviny a Rakúskom.',
    'ann.a5.title':'Oficiálne oznámenie — Odovzdanie poverovacích listín','ann.a5.desc':'Jeho Excelencia pán Cissé Yacouba, mimoriadny a splnomocnený veľvyslanec Republiky Pobrežia Slonoviny, odovzdal svoje poverovacie listiny spolkovému prezidentovi Rakúskej republiky na oficiálnej ceremónii v paláci Hofburg vo Viedni.',
    'ann.a6.title':'Pobrežie Slonoviny a CTBTO uzavreli v Abidžane partnerstvo v oblasti jadrovej bezpečnosti','ann.a6.desc':'Dňa 26. júna 2026 podpísali v Abidžane Pobrežie Slonoviny a Organizácia Zmluvy o všeobecnom zákaze jadrových skúšok (CTBTO) partnerskú dohodu zameranú na posilnenie Medzinárodného monitorovacieho systému (IMS). Veľvyslanec Cissé Yacouba zastupoval pobrežnoslonovinskú delegáciu po boku ministerky zahraničných vecí Nialé Kaba a výkonného tajomníka Roberta Floyda.','ann.a6.date':'26. júna 2026',
