    'pays.blurb.at':'Zemlja domaćin Veleposlanstva. Beč je također domaćin brojnim međunarodnim organizacijama (UNIDO, IAEA, UNODC).','pays.blurb.hu':'Država članica Europske unije, smještena u srcu srednje Europe.','pays.blurb.si':'Alpska zemlja na raskrižju srednje Europe, članica Europske unije.','pays.blurb.sk':'Mlada srednjoeuropska republika, članica Europske unije i eurozone.','pays.blurb.hr':'Zemlja na obali Jadranskog mora, posljednja zemlja koja se pridružila Europskoj uniji (2013.).','pays.blurb.rs':'Zemlja kandidatkinja za članstvo u Europskoj uniji, smještena u srcu Balkana.','pays.blurb.ro':'Velika jugoistočnoeuropska zemlja, članica Europske unije od 2007.','pays.blurb.ba':'Balkanska država u procesu europske integracije, na raskrižju kultura.','pays.blurb.md':'Istočnoeuropska država koja se približava Europskoj uniji.',
