    'dl.info.title':'Informații importante', 'dl.info.text':'Formularele trebuie imprimate, completate și semnate înainte de programare. Toate plățile se efectuează exclusiv online.',
    'dl.f01.eyebrow':'Pașaport', 'dl.f01.title':'Formular de cerere pentru pașaport', 'dl.f01.sub':'Pașaport ordinar / biometric în străinătate', 'dl.f01.desc':'Formular oficial al Ministerului Securității. Se completează și se semnează înainte de programarea consulară. Anexați documentele justificative.', 'dl.f01.size':'PDF · 68 KB',
    'dl.f02.eyebrow':'Înmatriculare', 'dl.f02.title':'Fișă de înmatriculare consulară', 'dl.f02.sub':"Înscriere în registrul cetățenilor din Côte d'Ivoire din străinătate", 'dl.f02.desc':"Obligatorie pentru orice cetățean din Côte d'Ivoire care are reședința în Austria. Înmatricularea facilitează accesul la serviciile consulare și vă protejează drepturile în străinătate.", 'dl.f02.size':'PDF · 124 KB',
    'dl.f03.eyebrow':'Minor', 'dl.f03.title':'Declarație parentală', 'dl.f03.sub':'Autorizație pentru pașaportul și/sau certificatul de naștere al unui minor', 'dl.f03.desc':'Autorizație emisă de unul sau ambii părinți pentru eliberarea unui pașaport sau a unui certificat de naștere pentru un copil minor. Este necesară o semnătură legalizată.', 'dl.f03.size':'PDF · 100 KB',
