    'dl.f05.eyebrow':'Stare civilă', 'dl.f05.title':'Transcrierea certificatului de naștere', 'dl.f05.sub':"Copii născuți în străinătate din părinți din Côte d'Ivoire", 'dl.f05.desc':"Formular utilizat pentru înregistrarea unui certificat de naștere străin în registrele de stare civilă din Côte d'Ivoire. Obligatoriu pentru obținerea cetățeniei și a pașaportului.", 'dl.f05.size':'PDF · 131 KB',
    'dl.f06.eyebrow':'Procură', 'dl.f06.title':'Procură consulară', 'dl.f06.sub':'Mandat pentru a acționa în numele unui terț', 'dl.f06.desc':"Permite unei persoane desemnate să efectueze demersuri administrative în numele dumneavoastră la ambasadă sau pe teritoriul Côte d'Ivoire.", 'dl.f06.size':'PDF · 89 KB',
    'dl.f07.eyebrow':'Legalizare', 'dl.f07.title':'Cerere de legalizare', 'dl.f07.sub':'Legalizarea documentelor administrative sau notariale', 'dl.f07.desc':"Formular pentru legalizarea documentelor din Côte d'Ivoire sau străine destinate utilizării în Côte d'Ivoire sau într-o țară terță. Aplicabil actelor notariale, administrative și comerciale.", 'dl.f07.size':'PDF · 121 KB',
    'dl.f08.eyebrow':'Permis de liberă trecere', 'dl.f08.title':'Cerere de permis de liberă trecere', 'dl.f08.sub':'Document de călătorie provizoriu în caz de urgență', 'dl.f08.desc':"Document de călătorie temporar eliberat în caz de pierdere, furt sau expirare a pașaportului. Valabil pentru o călătorie dus spre Côte d'Ivoire.", 'dl.f08.size':'PDF · 139 KB',
