    'pays.blurb.at':'Țara gazdă a Ambasadei. Viena găzduiește, de asemenea, numeroase organizații internaționale (ONUDI, AIEA, UNODC).', 'pays.blurb.hu':'Stat membru al Uniunii Europene, situat în inima Europei Centrale.', 'pays.blurb.si':'Țară alpină la răscrucea Europei Centrale, membră a Uniunii Europene.', 'pays.blurb.sk':'Tânără republică din Europa Centrală, membră a Uniunii Europene și a zonei euro.', 'pays.blurb.hr':'Țară de coastă la Marea Adriatică, ultima țară care a aderat la Uniunea Europeană (2013).', 'pays.blurb.rs':'Țară candidată la aderarea la Uniunea Europeană, situată în inima Balcanilor.', 'pays.blurb.ro':'Mare țară din sud-estul Europei, membră a Uniunii Europene din 2007.', 'pays.blurb.ba':'Stat balcanic aflat în proces de integrare europeană, la răscrucea culturilor.', 'pays.blurb.md':'Stat din Europa de Est aflat în proces de apropiere de Uniunea Europeană.',
