    'cta.title':'Aveți nevoie de asistență consulară?', 'cta.desc':'Echipa noastră este la dispoziția dumneavoastră pentru a vă însoți în toate demersurile administrative. Faceți o programare online sau contactați-ne direct.', 'cta.btn1':'Faceți o programare', 'cta.btn2':'Consultați serviciile',
    'ann.h1':'Informații și anunțuri', 'ann.desc':"Găsiți aici toate informațiile oficiale, avizele importante și anunțurile Ambasadei Côte d'Ivoire la Viena.",
    'ann.pinned.label':'Fixat — Urgent', 'ann.pinned.title':"Închidere excepțională — Ziua Națională a Republicii Côte d'Ivoire", 'ann.pinned.desc':"Ambasada Côte d'Ivoire la Viena va fi <strong>închisă vineri, 7 august 2026</strong>, cu ocazia Zilei Naționale a Republicii Côte d'Ivoire (a 66-a aniversare a independenței). Serviciile vor fi reluate normal luni, 10 august 2026, de la ora 09.30.", 'ann.pinned.date':'Publicat pe 25 mai 2026',
    'ann.filter.all':'Toate', 'ann.filter.urgent':'Urgente', 'ann.filter.admin':'Administrativ', 'ann.filter.event':'Evenimente', 'ann.filter.communique':'Comunicate',
    'ann.cat.mission':'Misiune economică', 'ann.cat.diplo':'Diplomație', 'ann.cat.actu':'Actualitate', 'ann.cat.communique':'Comunicat',
    'ann.btn.read':' Citiți articolul', 'ann.btn.readfull':' Citiți comunicatul integral', 'ann.empty':'Niciun anunț în această categorie momentan.',
    'ann.sidebar.links':'Legături utile', 'ann.sidebar.passport':'Reînnoirea pașaportului', 'ann.sidebar.visa':'Cerere de viză', 'ann.sidebar.civil':'Stare civilă', 'ann.sidebar.rdv':'Faceți o programare', 'ann.sidebar.hours':'Program de funcționare', 'ann.sidebar.contact':'Contact direct',
    'ann.sub.title':'Primiți anunțurile', 'ann.sub.desc':'Înscrieți-vă pentru a fi notificat despre noile anunțuri și informații importante.', 'ann.sub.btn':'Abonați-vă la alerte',
    'ann.a1.title':"Misiune economică: Aka Aouélé conduce o delegație a Consiliului Economic, Social, de Mediu și Cultural (CESEC) în Austria", 'ann.a1.desc':"Președintele CESEC, Aka Aouélé, a condus o delegație ivoriană în Austria în cadrul unei misiuni economice menite să consolideze schimburile și cooperarea dintre Côte d'Ivoire și partenerii săi europeni.",
    'ann.a2.title':"Diplomația ivoriană onorată la Viena: Côte d'Ivoire preia președinția Organizației Tratatului de Interzicere Totală a Experiențelor Nucleare", 'ann.a2.desc':"Côte d'Ivoire a preluat președinția Comisiei Pregătitoare a Organizației Tratatului de Interzicere Totală a Experiențelor Nucleare (CTBTO), marcând o etapă majoră a diplomației ivoriene pe scena internațională de la Viena.",
    'ann.a3.title':"Energie nucleară civilă: Côte d'Ivoire pledează pentru un sprijin consolidat din partea Agenției Internaționale pentru Energie Atomică", 'ann.a3.desc':"Côte d'Ivoire și-a exprimat la Viena, în cadrul lucrărilor AIEA, dorința de a beneficia de un sprijin consolidat în cadrul dezvoltării programului său nuclear civil.",
    'ann.a4.title':"Diplomația ivoriană în Austria: ambasadorul Cissé Yacouba discută cu guvernatorul landului Vorarlberg", 'ann.a4.desc':"Excelența Sa domnul Cissé Yacouba, Ambasadorul Côte d'Ivoire în Austria, s-a întâlnit cu guvernatorul landului Vorarlberg în cadrul consolidării relațiilor bilaterale dintre Côte d'Ivoire și Austria.",
    'ann.a5.title':"Comunicat oficial — Prezentarea scrisorilor de acreditare", 'ann.a5.desc':"Excelența Sa domnul Cissé Yacouba, Ambasador Extraordinar și Plenipotențiar al Republicii Côte d'Ivoire, și-a prezentat scrisorile de acreditare Președintelui Federal al Republicii Austria în cadrul unei ceremonii oficiale la Palatul Hofburg din Viena.",
    'ann.a6.title':"Côte d'Ivoire și CTBTO încheie la Abidjan un parteneriat în domeniul securității nucleare", 'ann.a6.desc':"La 26 iunie 2026, la Abidjan, Côte d'Ivoire și Organizația Tratatului de Interzicere Totală a Experiențelor Nucleare (CTBTO) au semnat un acord de parteneriat vizând consolidarea Sistemului Internațional de Monitorizare (IMS). Ambasadorul Cissé Yacouba a reprezentat delegația ivoriană alături de Ministrul Afacerilor Externe Nialé Kaba și Secretarul Executiv Robert Floyd.", 'ann.a6.date':'26 iunie 2026',
